# Generated by unmv. Sources only an unmv helper; mv is unchanged.
function unmv() (
    local unmv_name=mv unmv_type unmv_value unmv_next unmv_option unmv_path unmv_depth
    local -a unmv_words
    export UNMV_CONTEXT_SHELL=bash UNMV_CONTEXT_TYPE=unknown
    export UNMV_CONTEXT_COMMAND='' UNMV_CONTEXT_DESCRIPTION=''
    export UNMV_DEFAULT_PROMPT_ANSWER='@UNMV_DEFAULT_PROMPT_ANSWER@'
    for ((unmv_depth=0; unmv_depth<16; unmv_depth++)); do
        unmv_type=$(builtin type -t -- "$unmv_name" 2>/dev/null)
        if [[ $unmv_type == alias ]]; then
            unmv_value=$(builtin alias "$unmv_name")
            UNMV_CONTEXT_DESCRIPTION+="$unmv_value; "
            unmv_value=${unmv_value#*=}
            # alias emits one quoted value. Only simple words and flags are accepted.
            [[ ${unmv_value:0:1} == "'" && ${unmv_value: -1} == "'" ]] || break
            unmv_value=${unmv_value:1:${#unmv_value}-2}
            builtin read -r -a unmv_words <<< "$unmv_value"
            unmv_next=${unmv_words[0]}
            [[ $unmv_next =~ ^[a-zA-Z0-9_./+-]+$ ]] || break
            for unmv_option in "${unmv_words[@]:1}"; do
                [[ $unmv_option =~ ^-[finv]+$ || $unmv_option == --force || $unmv_option == --interactive || $unmv_option == --no-clobber || $unmv_option == --verbose ]] || break 2
            done
            if [[ $unmv_next != "$unmv_name" ]]; then
                unmv_name=$unmv_next
                continue
            fi
            if builtin declare -F "$unmv_name" >/dev/null; then
                UNMV_CONTEXT_DESCRIPTION+="$(builtin declare -f "$unmv_name")"
                break
            fi
        elif [[ $unmv_type == function ]]; then
            UNMV_CONTEXT_DESCRIPTION+="$(builtin declare -f "$unmv_name")"
            break
        elif [[ $unmv_type != file ]]; then
            UNMV_CONTEXT_DESCRIPTION+="unknown command $unmv_name ($unmv_type)"
            break
        fi
        unmv_path=$(builtin hash -t "$unmv_name" 2>/dev/null) || unmv_path=$(builtin type -P -- "$unmv_name" 2>/dev/null)
        if [[ -n $unmv_path ]]; then
            UNMV_CONTEXT_TYPE=external
            UNMV_CONTEXT_COMMAND=$unmv_path
            UNMV_CONTEXT_DESCRIPTION+="$unmv_path"
        fi
        break
    done
    command @UNMV_BIN@ "$@"
)
